export const BODY: string = "\n<p>مرشح صورة يغيّر جو صورة بنقرة واحدة: يغيّر الألوان والتباين والنغمة، محولًا صورة عادية إلى صورة منمقة.</p>\n<p>المرشحات هي أسرع تعديل في التصوير: لمسة واحدة قد تجعل صورة تشعر بالقدم أو الدراما أو الدفء أو البرودة، دون أي ضبط يدوي.</p>\n<p>يشرح هذا الدليل كيف تعمل المرشحات وما تفعله الأنماط الـ11 وكيف تستخدمها جيدًا: يغطي الشدة والمقارنة والاتساق وأخطاء تجعل صورًا مرشحة تبدو رخيصة.</p>\n<h2 id=\"what-filters-do\">ماذا تفعل مرشحات الصور فعلًا؟</h2>\n<p>مرشح يطبق مزيجًا محددًا مسبقًا من تغييرات اللون والتباين والنغمة على صورة: كل مرشح وصفة: ألوان أدفأ أو تباين أنعم أو سود باهتة أو لوحة أبرد.</p>\n<p>التغييرات تحدث كلها معًا: بدل ضبط السطوع والتباين والتشبع منفصلين، يطبق مرشح مجموعة منسقة من التغييرات في خطوة واحدة. والمرشحات لا تضيف تفاصيل إلى صورة: تغيّر كيف يبدو التفصيل الموجود، مغيرة الجو دون تغيير الشخص أو التكوين.</p>\n<p>فكر في مرشح كصبغة عدسة: المشهد يبقى نفسه، لكن الألوان والضوء يشعران بالاختلاف، كأن الصورة التُقطت في عصر آخر أو مكان آخر.</p>\n<h2 id=\"eleven-filter-styles\">أنماط المرشحات الـ11</h2>\n<p>توفر الأداة 11 نمط مرشح: تدرج رمادي وسيبيا وفينتج ودافئ وبارد وتباين عالٍ وباهت غير لامع ودرامي وأبيض وأسود نوير وساعة ذهبية وعكس: كل منها يعطي مظهرًا مختلفًا.</p>\n<p>تدرج رمادي يزيل كل اللون ويحوّل الصورة إلى أبيض وأسود: وأبيض وأسود نوير يفعل نفسه بتباين أقوى، معطيًا أبيض وأسود دراميًا كفيلم. وسيبيا يضيف صبغة بنية دافئة تشعر بالقدم والحنين: وفينتج مشابه لكنه أنعم، بألوان باهتة ومظهر فيلم خفيف.</p>\n<p>ودافئ يضيف صبغة ذهبية، وبارد يضيف صبغة زرقاء، وساعة ذهبية تحاكي ضوء الغروب الدافئ: وتباين عالٍ يضيف قوة، وباهت غير لامع يلطّف السود، ودرامي يعمّق الظلال.</p>\n<h2 id=\"filter-intensity\">شدة المرشح: من 0 بالمئة إلى 100 بالمئة</h2>\n<p>الشدة تتحكم في كم قوة يُطبق المرشح: عند 100 بالمئة، يظهر التأثير الكامل، بينما عند 0 بالمئة، لا تتغير الصورة.</p>\n<p>تثبيت الشدة تحت 100 بالمئة يمزج البكسلات المرشحة مجددًا نحو الأصل: مرشح فينتج بنسبة 45 بالمئة يعطي غسيل فيلم خفيفًا دون إطفاء النغمات الطبيعية. وشدة أقل غالبًا هي الخيار الأفضل: مرشح بقوة كاملة قد يطغى على الصورة، بينما نفس المرشح بنسبة 50 بالمئة يضيف جوًا دون إخفاء الشخص.</p>\n<p>جرّب المرشح بنسبة 100 بالمئة أولًا لرؤية طابعه، ثم اخفض الشدة حتى يشعر التأثير جيدًا: المعاينة تتحدث مباشرة، فتستطيع إيجاد النقطة المثالية.</p>\n<h2 id=\"vintage-default\">لماذا فينتج هو الافتراضي</h2>\n<p>تختار الأداة فينتج بنسبة 100 بالمئة فور إسقاطك صورة: ذلك الافتراضي يعطيك تأثيرًا منتهيًا على اللوحة الرئيسية فورًا، لترى ما تستطيع الأداة فعله.</p>\n<p>فينتج مرشح ناعم وممتع: ألوانه الباهتة وتباينه الناعم يناسبان معظم الصور، ونادرًا يجعل صورة تبدو أسوأ، ما يجعله قيمة افتراضية آمنة. وانقر أي بلاطة أخرى في إعدادات المرشح السريعة للتغيير، أو انقر \"إعادة تعيين\" للعودة إلى الأصل: الافتراضي نقطة بداية لا التزام.</p>\n<p>وإذا لم يناسب فينتج صورتك، جرّب دافئ أو ساعة ذهبية لإحساس مشابه بألوان مختلفة: المرشحات الدافئة الثلاثة تشترك في جو لكنها تختلف في النغمة.</p>\n<h2 id=\"grayscale-vs-noir\">تدرج رمادي أم أبيض وأسود نوير</h2>\n<p>تدرج رمادي يزيل اللون ويترك صورة بسيطة بالأبيض والأسود: إنها نظيفة ومحايدة وصادقة، تُظهر الصورة كما هي بالضبط، دون لون.</p>\n<p>وأبيض وأسود نوير يزيل اللون ويضيف تباينًا قويًا: تتعمق السود وتفتّح البيض وتكسب الصورة جودة درامية كفيلم. واستخدم تدرج رمادي عندما يجب أن تشعر الصورة بالهدوء والتوثيق: واستخدم أبيض وأسود نوير عندما يجب أن تشعر بالدراما، بظلال قوية وإضاءات بارزة.</p>\n<p>وكلاهما يناسب عمارة وتصوير شوارع وصورًا شخصية بتعبيرات قوية: الاختيار يعتمد على إن أردت أبيض وأسود هادئًا أو دراميًا.</p>\n<h2 id=\"sepia-vintage-matte-golden\">سيبيا وفينتج وباهت غير لامع وساعة ذهبية</h2>\n<p>سيبيا يضيف صبغة بنية دافئة تشعر بالقدم: يناسب صورًا تاريخية وذكريات عائلية وأي صورة يجب أن تشعر بأنها من عصر آخر.</p>\n<p>فينتج أنعم من سيبيا، بألوان باهتة ومظهر فيلم خفيف: يناسب صورًا عفوية ومنشورات اجتماعية، حيث الحنين يجب أن يشعر خفيفًا لا ثقيلًا. وباهت غير لامع يلطّف السود، معطيًا الصورة جودة باهتة كفيلم: يناسب صورًا شخصية وصور أسلوب حياة، حيث جو ناعم وحالم يعمل جيدًا.</p>\n<p>وساعة ذهبية تحاكي ضوء الغروب الدافئ: تضيف توهجًا ذهبيًا يناسب مناظر وصورًا شخصية وأي صورة ملتقطة بضوء دافئ.</p>\n<h2 id=\"warm-vs-cool\">مرشحات دافئة أم باردة</h2>\n<p>دافئ يضيف صبغة ذهبية وصفراء تشعر بالشمس والترحيب: يناسب صورًا شخصية وطعامًا ومناظر، حيث توهج دافئ يجعل الصورة تشعر بالترحيب.</p>\n<p>وبارد يضيف صبغة زرقاء تشعر بالهدوء والحدة: يناسب مشاهد شتاء وعمارة ومنتجات تقنية، حيث لوحة باردة تشعر بالحداثة والنظافة. والاختيار يعتمد على الجو الذي تريده: مرشح دافئ على مشهد ثلجي يشعر بالخطأ، بينما مرشح بارد على غروب شاطئ يصارع الدفء الطبيعي.</p>\n<p>جرّب الاثنين في نفس الصورة وقارن: الفرق يقفز إلى العين فورًا، والصحيح غالبًا يشعر بأنه ينتمي إلى المشهد.</p>\n<h2 id=\"invert-filter\">مرشح العكس</h2>\n<p>عكس يقلب كل لون إلى عكسه: الأسود يصبح أبيض والأزرق يصبح برتقاليًا والأحمر يصبح سماويًا: والنتيجة تبدو كسالب فوتوغرافي.</p>\n<p>عكس هو أكثر مرشح غير عادي في المجموعة، ويناسب نطاقًا ضيقًا من الاستخدامات: يعمل لتأثيرات فنية ولمراجعة صورة ولإنشاء رسم لافت. ولمعظم الصور، عكس هو حداثة أكثر من تعديل عملي: صورة شخصية معكوسة تبدو غريبة، ومنظر معكوس يبدو أجنبيًا.</p>\n<p>استخدم عكس باعتدال، لغرض إبداعي محدد: صورة واحدة معكوسة في سلسلة قد تكون لافتة، بينما خلاصة كاملة منها مربكة.</p>\n<h2 id=\"hold-to-view-original\">الاحتفاظ لرؤية الأصل</h2>\n<p>زر \"الاحتفاظ لرؤية الأصل\" يُظهر الصورة دون مرشح أثناء استمرارك بالضغط: وعند الإفلات، تعود النسخة المرشحة.</p>\n<p>هذه أسرع طريقة للحكم على مرشح: استمر بالضغط لرؤية الأصل، وأفلت لرؤية التعديل، ويقفز الفرق إلى العين فورًا. واستخدمه بعد كل تغيير مرشح: مرشح يبدو جيدًا وحده قد يبدو سيئًا بجانب الأصل، وزر الاحتفاظ يجعل المقارنة فورية.</p>\n<p>والزر مفيد خاصة للمرشحات الدقيقة: مرشح فينتج بنسبة 45 بالمئة صعب الحكم عليه وحده، لكن المقارنة بالاحتفاظ تُظهر بالضبط ما تغيّر.</p>\n<h2 id=\"side-by-side-compare\">مقارنة جنبًا إلى جنب</h2>\n<p>توفر الأداة أيضًا مقارنة مقسمة جنبًا إلى جنب، تُظهر الأصل والنسخة المرشحة معًا: إنها أفضل طريقة للحكم على مرشح بعناية.</p>\n<p>العرض المقسم يُظهر بالضبط أي مناطق تغيرت وبكم: البشرة والسماء والظلال تُرى في النسختين معًا. واستخدم العرض المقسم عند الاختيار بين مرشحين: طبّق واحدًا وراجع القسمة، ثم طبّق الآخر وقارن مجددًا: المرشح الأفضل غالبًا واضح.</p>\n<p>ولمراجعة نهائية، استخدم المقارنة بملء الشاشة: العرض الكبير يُظهر تفاصيل تخفيها معاينة صغيرة، بما فيها تغييرات لون دقيقة في البشرة والسماء.</p>\n<h2 id=\"filters-for-portraits\">مرشحات للصور الشخصية</h2>\n<p>الصور الشخصية تناسب مرشحات ناعمة: فينتج ودافئ وباهت غير لامع تضيف جوًا دون تغيير الوجه، بينما مرشحات قوية قد تجعل البشرة تبدو غير طبيعية.</p>\n<p>تجنب تباين عالٍ ودرامي في صور شخصية، ما لم يطلب الجو ذلك: ظلال قوية قد تسنّ الوجه وتجعل البشرة تبدو قاسية. وأبيض وأسود نوير يناسب صورًا شخصية بتعبيرات قوية: الأبيض والأسود الدرامي يؤكد العينين والعاطفة، لهذا هو مرشح صور شخصية كلاسيكي.</p>\n<p>وراجع نغمات البشرة بعد كل مرشح: مرشح يبدو جيدًا في الخلفية قد يحوّل الوجه إلى برتقالي أو أخضر أو رمادي، فراجع الشخص أولًا دائمًا.</p>\n<h2 id=\"filters-for-landscapes\">مرشحات للمناظر الطبيعية</h2>\n<p>المناظر تناسب مرشحات أقوى: ساعة ذهبية تضيف دفئًا إلى غروب، ودرامي يعمّق سماء كئيبة، وتباين عالٍ يضيف قوة إلى مشهد مسطح.</p>\n<p>فينتج وباهت غير لامع يناسبان مناظر ناعمة وحالمة: صباح ضبابي أو حقل هادئ يكسبان جوًا ناعمًا وحنينًا بمرشح باهت. وتجنب بارد في منظر دافئ: غروب بصبغة زرقاء يصارع الدفء الطبيعي، والنتيجة تبدو كخطأ أكثر من أسلوب.</p>\n<p>ولمنظر بسماء ساطعة، راجع الغيوم بعد الترشيح: مرشح قوي قد يقص الإضاءات ويحوّل السماء إلى بياض فارغ.</p>\n<h2 id=\"consistent-look\">كيف تختار مظهرًا متسقًا</h2>\n<p>مرشح متسق في صورك يخلق أسلوبًا مميزًا: المتابعون يتعلمون التعرف على عملك قبل قراءة اسمك، ما يبني هوية بصرية.</p>\n<p>اختر مرشحًا وشدة، واستخدمهما لسلسلة كاملة: خلاصة حيث كل صورة تشترك في نفس فينتج بنسبة 50 بالمئة تبدو معتنى بها، بينما مرشحات مختلطة تبدو عشوائية. وجرّب المرشح في أنواع صور مختلفة قبل الالتزام: مرشح يناسب مناظر قد لا يناسب صورًا شخصية، ومظهر متسق يحتاج مرشحًا يعمل في الاثنين.</p>\n<p>وراجع اختيار مرشحك من حين لآخر: الأنماط تتغير، ومرشح شعر بالانتعاش العام الماضي قد يشعر بالقدم الآن، فحدّثه عندما يتطور عملك.</p>\n<h2 id=\"formats-and-export\">الصيغ والتصدير</h2>\n<p>تقبل الأداة صيغ صور شائعة، بما فيها JPG وPNG وWebP وHEIC، بملفات حتى 20 MB: وتستطيع التصدير كـJPG أو PNG أو WebP حسب حاجتك.</p>\n<p>التصدير كـPNG أو WebP يحافظ على شفافية الصورة الأساسية: إذا كان مصدرك شعار PNG شفافًا، فالتصدير المرشح يحافظ على المناطق الشفافة سليمة، مع أن معظم المرشحات صُممت للصور. وللصور، JPG بضبط جودة عالية يعمل جيدًا: المرشحات لا تضيف كثيرًا إلى حجم الملف، فالتصدير يبقى قريبًا من الوزن الأصلي.</p>\n<p>ويظهر ضبط الجودة لتصديرات JPG وWebP، ويُخفى لـPNG، لأن PNG دون فقدان وليس له ضبط جودة لتغييره.</p>\n<h2 id=\"privacy-local-processing\">خصوصية: ترشيح دون رفع أي شيء</h2>\n<p>كل عمل المرشحات يحدث في متصفحك: صورك لا تُرفع أبدًا إلى خادم، وهو أمر مهم عندما تكون الصور شخصية أو صورًا عائلية أو عمل عملاء.</p>\n<p>هذه ميزة حقيقية مقابل محررات السحابة: صورة عائلية أو بورتريه خاص لا يجب أن يسافر إلى خادم لا تستطيع رؤيته، فقط لإضافة مرشح. وتزيل الأداة أيضًا بيانات GPS EXIF عند التصدير: صورة مرشحة منزلة من الأداة لا تحمل أي سجل لأين التُقطت.</p>\n<p>احتفظ بالصورة الأصلية دون مرشح: بمجرد أن يُسطّح مرشح في تصدير، لا يمكن إزالته من ذلك الملف، فالأصل هو نسختك النظيفة الوحيدة.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة عند استخدام المرشحات</h2>\n<p>أكثر خطأ شيوعًا استخدام مرشح بشدة كاملة عندما تكون قيمة أقل أفضل: مرشح فينتج بنسبة 100 بالمئة قد يطغى على الصورة، بينما نفس المرشح بنسبة 50 بالمئة يضيف جوًا دون إخفاء الشخص.</p>\n<p>خطأ آخر استخدام مرشح مختلف في كل صورة: خلاصة بمرشحات مختلطة تبدو عشوائية، بينما مرشح متسق يبني أسلوبًا مميزًا. وينسى الناس أيضًا مراجعة البشرة: مرشح يبدو جيدًا في الخلفية قد يحوّل الوجه إلى برتقالي أو أخضر أو رمادي، فراجع الشخص أولًا دائمًا.</p>\n<p>وأخيرًا، لا تكدّس مرشحات في الأداة: الأداة تطبق مرشحًا واحدًا في كل مرة، ومحاولة تكديسها بإعادة رفع الصورة المرشحة تضيف ضررًا مع كل جولة.</p>\n<h2 id=\"filters-for-travel\">مرشحات لصور السفر</h2>\n<p>صور السفر تمزج أشخاصًا ومناظر وطعامًا وعمارة، فتحتاج مرشحًا يعمل في كل شيء: فينتج بنسبة 50 بالمئة خيار آمن، لأن مظهره الناعم يناسب كل نوع تقريبًا.</p>\n<p>استخدم مرشحًا واحدًا لرحلة كاملة، ليبدو المجموع كرحلة واحدة: ألبوم سفر حيث كل صورة تشترك في نفس المرشح يبدو معتنى به، بينما مرشحات مختلطة تبدو عشوائية. وراجع الأشخاص في كل صورة سفر بعد الترشيح: مرشح منظر يبدو جيدًا في المشهد قد يحوّل المسافرين إلى برتقالي، فراجع الوجوه دائمًا.</p>\n<p>ولخلاصة سفر، راجع المرشح في صور اختبار قليلة قبل الالتزام: مرشح يناسب شاطئًا قد لا يناسب شارع مدينة، والرحلة تحتاج واحدًا يعمل في الاثنين.</p>\n<p>للعملية خطوة بخطوة، راجع <a href=\"/ar/blog/kayfiyya-tatbiq-murashshahat-ala-as-suwar/\">كيف تطبق مرشحات الصور</a>. وللمقارنة، اقرأ <a href=\"/ar/blog/murashshahat-as-suwar-muqaranah/\">مرشحات الصور مقارنة: كيف تختار مظهرًا متسقًا</a>، ولضبط الألوان بدقة استخدم <a href=\"/ar/taadil-tashabbu-as-sura/\">محرر تشبع الصور</a>. وجرّب الأنماط الـ11 مجانًا في <a href=\"/ar/murashshahat-as-suwar/\">مرشحات الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"أي مرشح صورة أفضل للصور الشخصية؟","answer":"فينتج أو دافئ أو باهت غير لامع بشدة معتدلة نحو 50 بالمئة: هذه تضيف جوًا دون تغيير الوجه. وتجنب تباين عالٍ ودرامي في صور شخصية، ما لم يطلب الجو ذلك، وراجع نغمات البشرة بعد كل مرشح."},{"question":"ماذا يفعل ضبط شدة المرشح؟","answer":"يتحكم في كم قوة يُطبق المرشح، من 0 بالمئة (الصورة الأصلية) إلى 100 بالمئة (التأثير الكامل): تثبيت فينتج على 45 بالمئة يمزج البكسلات المرشحة مجددًا نحو الأصل، معطيًا غسيل فيلم خفيفًا."},{"question":"لماذا تبدأ الأداة بفينتج محددًا؟","answer":"فينتج بنسبة 100 بالمئة هو الافتراضي لترى تأثيرًا منتهيًا على اللوحة الرئيسية فور رفع الصورة: إنه مرشح ناعم وممتع يناسب معظم الصور. وانقر أي بلاطة أخرى للتغيير، أو \"إعادة تعيين\" للعودة إلى الأصل."},{"question":"هل أستطيع تطبيق مرشحين على نفس الصورة؟","answer":"ليس في خطوة واحدة: تطبق الأداة مرشحًا واحدًا في كل مرة. وإعادة رفع صورة مرشحة لإضافة مرشح ثانٍ ممكنة، لكنها تضيف ضررًا مع كل جولة. واختر المرشح الواحد الذي يناسب المظهر الذي تريده أفضل."},{"question":"هل تغيّر المرشحات دقة صورتي؟","answer":"لا، تغيّر المرشحات الألوان والتباين والنغمة، لكن الأبعاد بالبكسلات تبقى نفسها: مصغرات المعاينة صغيرة، لكن الملف المنزّل يُعالج بدقة كاملة، فالتصدير حاد مثل الأصل."},{"question":"هل تطبيق مرشحات على صورة شخصية في أداة متصفح آمن؟","answer":"نعم، لأن كل المعالجة تحدث محليًا في متصفحك ولا يُرفع شيء إلى خادم: وتزيل الأداة أيضًا بيانات GPS EXIF عند التصدير. واحتفظ بالملف الأصلي إذا أردت تجربة مرشح آخر لاحقًا."}];
